<section>
    <div class="section-heading"><div><p class="eyebrow">Equipe</p><h1>Comissão técnica · <?= App\Core\View::e($team['name']) ?></h1></div><?php if ($canManage): ?><a class="button" href="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/comissao/nova')) ?>">Novo membro</a><?php endif; ?></div>
    <form class="search-form" method="get" action="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/comissao')) ?>"><label>Funcao <select name="staff_role_id"><option value="">Todas</option><?php foreach ($roles as $role): ?><option value="<?= (int) $role['id'] ?>" <?= (string) ($query['staff_role_id'] ?? '') === (string) $role['id'] ? 'selected' : '' ?>><?= App\Core\View::e($role['name']) ?></option><?php endforeach; ?></select></label><label>Status <select name="status"><option value="">Todos</option><?php foreach (['active' => 'Ativo', 'inactive' => 'Inativo', 'ended' => 'Encerrado', 'draft' => 'Rascunho'] as $key => $label): ?><option value="<?= $key ?>" <?= ($query['status'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button></form>
    <div class="table-wrap"><table><thead><tr><th>Nome</th><th>Funcao</th><th>Contato</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= App\Core\View::e($item['full_name']) ?></strong><?php if ($item['display_name']): ?><br><small><?= App\Core\View::e($item['display_name']) ?></small><?php endif; ?></td><td><?= App\Core\View::e($item['role_name']) ?></td><td><?= App\Core\View::e($item['email'] ?: $item['phone'] ?: 'Não informado') ?></td><td><?= App\Core\View::e($item['status']) ?></td><td><?php if ($canManage): ?><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/comissao/' . $item['id'] . '/editar')) ?>">Editar</a><?php endif; ?></td></tr><?php endforeach; ?><?php if ($items === []): ?><tr><td colspan="5">Nenhum membro encontrado.</td></tr><?php endif; ?></tbody></table></div>
    <p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'])) ?>">Voltar para equipe</a></p>
</section>
